catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading) {
      return;
   }

	if (newValue=="yes"){
			g_form.setValue('submitter_name','');//Make sure the field is emptied if it has been previously populated

			var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMUtils'); 
			ga.addParam('sysparm_name', 'getEmployeeAndManager'); 
			ga.getXML(function(response){
				var result = JSON.parse(response.responseXML.documentElement.getAttribute("answer"));
				//g_form.setValue("opened_for", '');
				//alert(result);
				g_form.setValue('complainant_name', result.employee);
				g_form.setValue('complainant_manager', result.manager);

			});
	}
	else
	{
			g_form.setValue('complainant_name', "");
			g_form.setValue('complainant_manager', "");

	}


}
